<script>
(() => { const data=@json($galleryData); let color=@json($defaultColorKey), index=0; const image=document.getElementById('member-detail-image'); const counter=document.querySelector('.member-detail-counter'); const caption=document.querySelector('.member-detail-caption small'); const thumbs=[...document.querySelectorAll('[data-member-thumb]')]; const render=()=>{const items=data[color]?.images||[];if(!items.length)return;index=Math.min(index,items.length-1);const item=items[index];image.src=item.src;if(counter)counter.textContent=`${String(index+1).padStart(2,'0')} / ${String(items.length).padStart(2,'0')}`;if(caption)caption.textContent=`${item.label} · YZA Automotive`;thumbs.forEach((t,i)=>t.classList.toggle('is-active',i===index));};document.querySelector('[data-member-gallery-prev]')?.addEventListener('click',()=>{const n=data[color]?.images?.length||1;index=(index-1+n)%n;render()});document.querySelector('[data-member-gallery-next]')?.addEventListener('click',()=>{const n=data[color]?.images?.length||1;index=(index+1)%n;render()});thumbs.forEach(t=>t.addEventListener('click',()=>{index=Number(t.dataset.memberThumb);render()}));document.querySelectorAll('[data-member-color]').forEach(button=>button.addEventListener('click',()=>{color=button.dataset.memberColor;index=0;document.getElementById('member-detail-color').textContent=button.dataset.label;document.querySelectorAll('[data-member-color]').forEach(item=>item.classList.toggle('is-active',item===button));render()}));render();})();
</script>
